pub fn with_registered_value<R>(&self, f: impl FnOnce(&Self) -> R) -> R {
    struct Reset<'a>(&'a Cell<bool>, bool);

    impl Drop for Reset<'_> {
        fn drop(&mut self) {
            self.0.set(self.1);
        }
    }

    let _reset = Reset(
        &self.in_registered_value,
        self.in_registered_value.replace(true),
    );
    f(self)
}

