pub fn with_property_declaration<R>(
    &mut self,
    property_id: PropertyIdRef<'a>,
    cb: impl FnOnce(&Self) -> R,
) -> R {
    self.property_declaration_context.set(property_id);
    let r = cb(self);
    self.property_declaration_context.clear();
    r
}

